import{_ as a,o as r,c as e,a2 as o}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"技术支持 - 我的工单","description":"","frontmatter":{"title":"技术支持 - 我的工单"},"headers":[],"relativePath":"ops-knowledge-base/presales-support/my-tickets.md","filePath":"ops-knowledge-base/presales-support/my-tickets.md","lastUpdated":1788259091000}'),s={name:"ops-knowledge-base/presales-support/my-tickets.md"};function l(n,t,i,p,g,d){return r(),e("div",null,[...t[0]||(t[0]=[o('<h2 id="一、功能概述" tabindex="-1">一、功能概述 <a class="header-anchor" href="#一、功能概述" aria-label="Permalink to &quot;一、功能概述&quot;">​</a></h2><p>工单系统是平台为用户提供的与支持团队沟通协作的工具，用户可通过提交工单反馈问题、寻求帮助，同时能在 “我的工单” 界面查看所有工单的状态及历史记录，便于跟踪问题处理进度，保障需求得到及时响应与解决。</p><h2 id="二、我的工单" tabindex="-1">二、我的工单 <a class="header-anchor" href="#二、我的工单" aria-label="Permalink to &quot;二、我的工单&quot;">​</a></h2><h3 id="一-功能入口" tabindex="-1">（一）功能入口 <a class="header-anchor" href="#一-功能入口" aria-label="Permalink to &quot;（一）功能入口&quot;">​</a></h3><p>通过平台导航路径<strong>后台客户中心****/ 技术支持 /</strong> 进入 “我的工单” 界面。</p><h3 id="二-功能说明" tabindex="-1">（二）功能说明 <a class="header-anchor" href="#二-功能说明" aria-label="Permalink to &quot;（二）功能说明&quot;">​</a></h3><p>界面展示工单记录，可通过 “等待中”“已回复”“用户回复”“已开启”“已关闭”“回答” 等标签筛选不同状态的工单。工单列表包含部门、主题、状态、最后更新时间等信息，方便用户快速了解工单情况。同时，支持通过右上角搜索框输入内容，快速查找特定工单。</p><h2 id="三、提交新工单" tabindex="-1">三、提交新工单 <a class="header-anchor" href="#三、提交新工单" aria-label="Permalink to &quot;三、提交新工单&quot;">​</a></h2><h3 id="一-功能入口-1" tabindex="-1">（一）功能入口 <a class="header-anchor" href="#一-功能入口-1" aria-label="Permalink to &quot;（一）功能入口&quot;">​</a></h3><p>在 “我的工单” 界面，点击 <strong>“提交新工单”</strong> 按钮，进入 “提交工单” 界面。</p><h3 id="二-功能说明-1" tabindex="-1">（二）功能说明 <a class="header-anchor" href="#二-功能说明-1" aria-label="Permalink to &quot;（二）功能说明&quot;">​</a></h3><ol><li><p><strong>基础信息填写</strong>：</p><ul><li><p><strong>姓名</strong>：系统自动填充用户姓名（如示例中的 “Rak Internal Test”），无需手动输入。</p></li><li><p><strong>邮件地址</strong>：系统自动填充用户邮件地址，确保工单通知能准确送达。</p></li><li><p><strong>主题</strong>：输入工单主题，需简洁明了地概括问题或需求，便于支持团队快速识别工单核心内容。</p></li><li><p><strong>问题分类</strong>：请根据您遇到的问题类型，选择最合适的问题分类。正确的分类有助于工单快速流转至对应处理团队，缩短响应时间。</p><ul><li><strong>性能问题</strong>：适用于平台产品或服务使用过程中的技术类问题，如系统报错、功能异常、网络连接故障、产品配置疑问等。技术支持团队具备专业技术知识，可对平台各类产品（如服务器、云服务、应用程序等）的技术问题进行诊断、排查、解决，还能提供产品使用指导、技术优化建议等服务。</li><li><strong>产品问题</strong>：涉及平台产品或服务的采购咨询、套餐选择、合作洽谈、销售政策疑问等与销售相关的需求时选择。销售团队负责解答产品价格、不同套餐内容及差异、优惠活动、合作模式等问题，协助用户选品，推进销售合作流程。比如，用户想了解云服务器不同配置套餐价格、新用户优惠活动，或有批量采购、长期合作意向，选此部门。</li><li><strong>财务问题</strong>：与账户账单相关的问题，如账单金额疑问、付款方式咨询、账单异常（重复扣费、未出账单等）处理等选该部门。账单团队专注账户财务事务，可核对解释账单明细、协助付款、处理发票申请及各类账单异常，保障账户财务清晰准确。</li><li><strong>相关服务</strong>：从下拉列表选择与工单相关的服务，若需隐藏非活跃产品，可勾选 “隐藏非活跃产品” 复选框。</li></ul></li><li><p><strong>优先级</strong>：下拉选择工单优先级（如 “中”），支持团队将根据优先级安排处理顺序，紧急问题可选择更高优先级。</p></li></ul></li><li><p><strong>信息描述</strong>：在 “信息” 编辑框中，详细描述问题或需求，可利用编辑工具（如加粗、斜体、添加链接等）优化内容展示，确保支持团队能清晰理解。</p></li><li><p><strong>附件上传</strong>：若有相关文件（如截图、日志等）辅助说明问题，可点击 “选择文件” 按钮上传附件，支持的文件类型包括.jpg、.gif、.jpeg、.png、.txt、.pdf，单个附件大小不超过 1M，且不支持中文名称。如需上传多个附件，点击 “+ 添加更多” 按钮即可。</p></li><li><p><strong>提交与取消</strong>：填写完成后，点击 <strong>“提交”</strong> 按钮，工单将提交至对应部门的支持团队；若放弃提交，点击 <strong>“取消”</strong> 按钮即可。</p></li></ol><p>通过工单系统，用户能高效地与平台支持团队协作，快速解决使用过程中遇到的问题，提升服务体验。</p>',13)])])}const u=a(s,[["render",l]]);export{c as __pageData,u as default};
